#!/usr/bin/env python3
# h714 census: enumerate every model-vs-hardware mismatch row from
# the mo_*_master.txt regenerated by h714_baseline.sh.  Emits:
#   h714_census.txt  corp mode lineno se sig hw=.. mo=..
#   h714_ops.txt     distinct operands (se sig), census order
#   h714_hw3.txt     se sig corp lineno | hw_rn hw_rd hw_ru | mo_rn mo_rd mo_ru
# Per-corpus totals must equal the promoted scoreboard.
import collections
CORPS = ["comb7","comb9","comb11","comb12","comb13","comb14",
         "comb15","comb16","comb17","comb18"]
def norm(line):
    t = line.split()
    return ("C2",) if t[0] == "C2" else tuple(t[1:3])
rows = []
totals = {}
per_corp = {}
for corp in CORPS:
    inputs = open(f"/root/h491/{corp}_inputs.txt").read().splitlines()
    hw = {}; mo = {}
    for mode in ("rn","rd","ru"):
        hw[mode] = open(f"/root/h491/{corp}_{mode}_status.txt").read().splitlines()
        mo[mode] = open(f"mo_{corp}_{mode}_master.txt").read().splitlines()
        assert len(hw[mode]) == len(mo[mode]) == len(inputs), (corp, mode)
    per_corp[corp] = (inputs, hw, mo)
    tot = 0
    for mode in ("rn","rd","ru"):
        for i,(a,b) in enumerate(zip(hw[mode],mo[mode])):
            if norm(a) != norm(b):
                tot += 1
                se, sig = inputs[i].split()
                rows.append((corp, mode, i, se, sig,
                             " ".join(norm(a)), " ".join(norm(b))))
    totals[corp] = tot
with open("h714_census.txt","w") as f:
    for r in rows:
        f.write("%s %s %d %s %s hw=%s mo=%s\n" % r)
print("per-corpus:", totals, "grand", sum(totals.values()))
ops = collections.OrderedDict()
for corp, mode, i, se, sig, a, b in rows:
    ops.setdefault((se,sig), (corp,i))
print("distinct operands:", len(ops))
with open("h714_ops.txt","w") as f:
    for (se,sig) in ops:
        f.write("%s %s\n" % (se,sig))
with open("h714_hw3.txt","w") as f:
    for (se,sig),(corp,i) in ops.items():
        inputs, hw, mo = per_corp[corp]
        h3 = ["/".join(norm(hw[m][i])) for m in ("rn","rd","ru")]
        m3 = ["/".join(norm(mo[m][i])) for m in ("rn","rd","ru")]
        f.write("%s %s %s %d | %s | %s\n"
                % (se, sig, corp, i, " ".join(h3), " ".join(m3)))
print("wrote h714_census.txt h714_ops.txt h714_hw3.txt")
